CREATE TABLE t1(a,b,c,PRIMARY KEY(b,c)); WITH RECURSIVE c1(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c1 WHERE x<1000) INSERT INTO t1 SELECT x,x%40,x/40 FROM c1; CREATE TABLE t2(a,b,c,d,e,f,PRIMARY KEY(b,c,d,e,f)); WITH RECURSIVE c2(x) AS (VALUES(0) UNION ALL SELECT x+1 FROM c2 WHERE x<242) INSERT INTO t2 SELECT x,x%3,(x/3)%3,(x/9)%3,(x/27)%3,(x/81)%3 FROM c2;